content:
:root {
  --bg-color: #0f172a;
  --panel-bg: #1e293b;
  --text-color: #f8fafc;
  --text-muted: #94a3b8;
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;
  --snake-color: #10b981;
  --food-color: #ef4444;
  --board-bg: #090d16;
  --border-color: #334155;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
}

.snake-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 450px;
  padding: 16px;
  gap: 16px;
}

.header {
  text-align: center;
  width: 100%;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  margin-bottom: 8px;
  background: linear-gradient(135deg, #34d399, #3b82f6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.score-board {
  display: flex;
  justify-content: space-around;
  width: 100%;
  background-color: var(--panel-bg);
  padding: 10px 16px;
  border-radius: 12px;
  border: 1px solid var(--border-color);
  font-size: 0.95rem;
  font-weight: 600;
}

.score-board span {
  color: var(--text-muted);
}

.score-board strong {
  color: var(--text-color);
  margin-left: 4px;
}

.game-board {
  position: relative;
  width: 320px;
  height: 320px;
  background-color: var(--board-bg);
  border: 3px solid var(--border-color);
  border-radius: 12px;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(20, 1fr);
  overflow: hidden;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
}

.cell {
  width: 100%;
  height: 100%;
}

.snake {
  background-color: var(--snake-color);
  border-radius: 4px;
  box-shadow: inset 0 0 2px rgba(0,0,0,0.3);
}

.food {
  background-color: var(--food-color);
  border-radius: 50%;
  transform: scale(0.85);
  box-shadow: 0 0 8px var(--food-color);
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(0.75); }
  100% { transform: scale(0.95); }
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, 60px);
  gap: 10px;
  width: 240px;
  margin: 0 auto;
}

.control-btn {
  background-color: var(--panel-bg);
  color: var(--text-color);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.1s, transform 0.1s;
}

.control-btn:active {
  background-color: var(--border-color);
  transform: scale(0.95);
}

.control-up {
  grid-column: 2;
  grid-row: 1;
}

.control-left {
  grid-column: 1;
  grid-row: 2;
}

.control-down {
  grid-column: 2;
  grid-row: 2;
}

.control-right {
  grid-column: 3;
  grid-row: 2;
}

.game-over-screen {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  border-radius: 10px;
  z-index: 10;
  animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.game-over-screen h2 {
  font-size: 1.5rem;
  color: var(--food-color);
  font-weight: 700;
}

.btn {
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.96);
}

.btn-primary {
  background-color: var(--accent-color);
  color: #fff;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
}

export interface Point {
  x: number;
  y: number;
}

export interface GameStatus {
  score: number;
  highScore: number;
  isGameOver: boolean;
  isPaused: boolean;
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Point, GameStatus } from './types';

const GRID_SIZE = 20;
const INITIAL_SNAKE: Point[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];
const INITIAL_DIRECTION: Point = { x: 0, y: -1 };
const INITIAL_SPEED = 120;

export default function App() {
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [direction, setDirection] = useState<Point>(INITIAL_DIRECTION);
  const [nextDirection, setNextDirection] = useState<Point>(INITIAL_DIRECTION);
  const [food, setFood] = useState<Point>({ x: 5, y: 5 });
  const [status, setStatus] = useState<GameStatus>({
    score: 0,
    highScore: 0,
    isGameOver: false,
    isPaused: false,
  });

  const directionRef = useRef(direction);
  directionRef.current = nextDirection;

  // ハイスコアの読み込み
  useEffect(() => {
    const savedHighScore = localStorage.getItem('snake_highscore');
    if (savedHighScore) {
      setStatus((prev) => ({ ...prev, highScore: parseInt(savedHighScore, 10) }));
    }
  }, []);

  // フードのランダム生成
  const generateFood = useCallback((currentSnake: Point[]): Point => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      const isOnSnake = currentSnake.some(
        (segment) => segment.x === newFood.x && segment.y === newFood.y
      );
      if (!isOnSnake) break;
    }
    return newFood;
  }, []);

  // ゲームリセット
  const restartGame = () => {
    const newSnake = INITIAL_SNAKE;
    setSnake(newSnake);
    setDirection(INITIAL_DIRECTION);
    setNextDirection(INITIAL_DIRECTION);
    setFood(generateFood(newSnake));
    setStatus((prev) => ({
      ...prev,
      score: 0,
      isGameOver: false,
      isPaused: false,
    }));
  };

  // 一時停止切り替え
  const togglePause = () => {
    if (status.isGameOver) return;
    setStatus((prev) => ({ ...prev, isPaused: !prev.isPaused }));
  };

  // 移動処理
  const moveSnake = useCallback(() => {
    if (status.isGameOver || status.isPaused) return;

    setSnake((prevSnake) => {
      const head = prevSnake[0];
      const currentDir = directionRef.current;
      const newHead: Point = {
        x: head.x + currentDir.x,
        y: head.y + currentDir.y,
      };

      setDirection(currentDir);

      // 壁衝突判定
      if (
        newHead.x < 0 ||
        newHead.x >= GRID_SIZE ||
        newHead.y < 0 ||
        newHead.y >= GRID_SIZE
      ) {
        setStatus((prev) => {
          const newHighScore = Math.max(prev.score, prev.highScore);
          localStorage.setItem('snake_highscore', newHighScore.toString());
          return { ...prev, isGameOver: true, highScore: newHighScore };
        });
        return prevSnake;
      }

      // 自分との衝突判定
      for (const segment of prevSnake) {
        if (segment.x === newHead.x && segment.y === newHead.y) {
          setStatus((prev) => {
            const newHighScore = Math.max(prev.score, prev.highScore);
            localStorage.setItem('snake_highscore', newHighScore.toString());
            return { ...prev, isGameOver: true, highScore: newHighScore };
          });
          return prevSnake;
        }
      }

      const newSnake = [newHead, ...prevSnake];

      // フードを食べたか
      if (newHead.x === food.x && newHead.y === food.y) {
        setFood(generateFood(newSnake));
        setStatus((prev) => {
          const newScore = prev.score + 10;
          const newHighScore = Math.max(newScore, prev.highScore);
          localStorage.setItem('snake_highscore', newHighScore.toString());
          return {
            ...prev,
            score: newScore,
            highScore: newHighScore,
          };
        });
      } else {
        newSnake.pop();
      }

      return newSnake;
    });
  }, [food, generateFood, status.isGameOver, status.isPaused]);

  // スコアに応じたゲームスピードの算出
  const currentSpeed = Math.max(
    50,
    INITIAL_SPEED - Math.floor(status.score / 50) * 10
  );

  // ゲームループ
  useEffect(() => {
    if (status.isGameOver || status.isPaused) return;
    const interval = setInterval(moveSnake, currentSpeed);
    return () => clearInterval(interval);
  }, [moveSnake, currentSpeed, status.isGameOver, status.isPaused]);

  // 方向変更ボタン・処理（nextDirection基準で反転を防止）
  const changeDirection = (newDir: Point) => {
    const currentDir = directionRef.current;
    if (
      (newDir.x !== 0 && currentDir.x === 0) ||
      (newDir.y !== 0 && currentDir.y === 0)
    ) {
      setNextDirection(newDir);
    }
  };

  // キーボード操作
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'Spacebar') {
        e.preventDefault();
        togglePause();
        return;
      }

      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault();
          changeDirection({ x: 0, y: -1 });
          break;
        case 'ArrowDown':
          e.preventDefault();
          changeDirection({ x: 0, y: 1 });
          break;
        case 'ArrowLeft':
          e.preventDefault();
          changeDirection({ x: -1, y: 0 });
          break;
        case 'ArrowRight':
          e.preventDefault();
          changeDirection({ x: 1, y: 0 });
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [status.isGameOver, status.isPaused]);

  // グリッド生成
  const renderBoard = () => {
    const cells = [];
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        const isSnake = snake.some((segment) => segment.x === x && segment.y === y);
        const isFood = food.x === x && food.y === y;

        let className = 'cell';
        if (isSnake) className += ' snake';
        if (isFood) className += ' food';

        cells.push(<div key={`${x}-${y}`} className={className} />);
      }
    }
    return cells;
  };

  return (
    <div className="snake-container">
      <div className="header">
        <h1>スネークゲーム</h1>
        <div className="score-board">
          <div>
            スコア: <strong>{status.score}</strong>
          </div>
          <div>
            ハイスコア: <strong>{status.highScore}</strong>
          </div>
        </div>
        <div style={{ marginTop: '10px' }}>
          <button
            className="btn btn-primary"
            onClick={togglePause}
            style={{ padding: '6px 16px', fontSize: '0.9rem' }}
          >
            {status.isPaused ? '再開' : '一時停止'}
          </button>
        </div>
      </div>

      <div className="game-board">
        {renderBoard()}
        {status.isGameOver && (
          <div className="game-over-screen">
            <h2>ゲームオーバー</h2>
            <button className="btn btn-primary" onClick={restartGame}>
              もう一度挑戦
            </button>
          </div>
        )}
      </div>

      <div className="controls">
        <button
          className="control-btn control-up"
          onClick={() => changeDirection({ x: 0, y: -1 })}
          aria-label="上"
        >
          ▲
        </button>
        <button
          className="control-btn control-left"
          onClick={() => changeDirection({ x: -1, y: 0 })}
          aria-label="左"
        >
          ◀
        </button>
        <button
          className="control-btn control-down"
          onClick={() => changeDirection({ x: 0, y: 1 })}
          aria-label="下"
        >
          ▼
        </button>
        <button
          className="control-btn control-right"
          onClick={() => changeDirection({ x: 1, y: 0 })}
          aria-label="右"
        >
          ▶
        </button>
      </div>
    </div>
  );
}
